// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertAll;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.mockito.Mockito.mock;

import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.Compare;
import org.eclipse.rdf4j.query.algebra.Filter;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.ValueConstant;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.PlanningGraphDomain;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.PlanningGraphDomains;
import org.eclipse.rdf4j.sail.lmdb.sketch.SketchSnapshotIdentity;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * {@link LmdbFilterSelectivityStats#planningRevision()} must advance whenever a value a planning read of the learned
 * filter surfaces returns can change: a validated plan-cache entry relies on it to know that the reads it replayed all
 * saw one state. A precompilation lease that needs a new surface cell at capacity evicts the oldest unleased cell; when
 * that cell holds observations, the learned-surface read of its filter answers differently afterwards.
 */
class LmdbFilterPlanningRevisionTruthTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI PREDICATE = VF.createIRI("urn:planning-revision-truth:value");
	private static final SketchSnapshotIdentity IDENTITY = new SketchSnapshotIdentity(11L, 22L, 33L);
	/** Comfortably above the surface-cell capacity (4096), so that every later lease evicts. */
	private static final int FILLING_FILTERS = 4200;

	@Test
	void precompilationEvictingAnEvidenceBearingSurfaceCellAdvancesThePlanningRevision(@TempDir Path directory) {
		LmdbFilterSelectivityStats stats = stats(directory);
		List<Filter> learned = new ArrayList<>();
		for (int index = 0; index < FILLING_FILTERS; index++) {
			Filter filter = filter("learned-" + index);
			stats.recordFilterOutcome(filter, 1L + index % 7, 3L);
			learned.add(filter);
		}
		List<Object> before = surfaceReads(stats, learned);
		long revision = stats.planningRevision();

		LmdbFilterSelectivityStats.ResolvedFilterCells lease = stats.resolveRuntimeFeedbackTarget(filter("new"));
		assertNotNull(lease, "COVERAGE_PREREQUISITE: the precompilation lease is granted at capacity");
		stats.releaseRuntimeFeedbackTarget(lease);
		List<Object> after = surfaceReads(stats, learned);

		assertAll(
				() -> assertNotEquals(before, after,
						"COVERAGE_PREREQUISITE: the lease evicted a cell that a learned-surface read returned"),
				() -> assertNotEquals(revision, stats.planningRevision(),
						"an eviction that changes a learned-surface read must advance the planning revision"));
	}

	@Test
	void precompilationEvictingOnlyEmptySurfaceCellsLeavesThePlanningRevision(@TempDir Path directory) {
		LmdbFilterSelectivityStats stats = stats(directory);
		for (int index = 0; index < FILLING_FILTERS; index++) {
			LmdbFilterSelectivityStats.ResolvedFilterCells lease = stats
					.resolveRuntimeFeedbackTarget(filter("empty-" + index));
			assertNotNull(lease, "COVERAGE_PREREQUISITE: every filling lease is granted");
			stats.releaseRuntimeFeedbackTarget(lease);
		}
		long revision = stats.planningRevision();

		LmdbFilterSelectivityStats.ResolvedFilterCells lease = stats.resolveRuntimeFeedbackTarget(filter("new"));
		assertNotNull(lease, "COVERAGE_PREREQUISITE: the precompilation lease is granted at capacity");
		stats.releaseRuntimeFeedbackTarget(lease);

		assertEquals(revision, stats.planningRevision(),
				"evicting cells that hold no observation changes no read and must not advance the revision");
	}

	private static List<Object> surfaceReads(LmdbFilterSelectivityStats stats, List<Filter> filters) {
		List<Object> reads = new ArrayList<>(filters.size());
		for (Filter filter : filters) {
			LmdbFilterSelectivityStats.LearnedSurfaceEstimate estimate = stats.estimateLearnedSurface(filter);
			reads.add(estimate == null ? "none"
					: Objects.hash(estimate.passRatio(), estimate.evidenceCount(), estimate.generalized()));
		}
		return reads;
	}

	private static LmdbFilterSelectivityStats stats(Path directory) {
		return new LmdbFilterSelectivityStats(directory.resolve("planning-revision-truth.rjes"),
				mock(TripleStore.class), mock(ValueStore.class), false, 0L, 0, false, () -> IDENTITY, 0, () -> true,
				() -> 0L);
	}

	private static Filter filter(String constant) {
		StatementPattern pattern = new StatementPattern(Var.of("s"), Var.of("_p", PREDICATE, true, true),
				Var.of("value"));
		Filter filter = new Filter(pattern,
				new Compare(Var.of("value"), new ValueConstant(VF.createLiteral(constant))));
		PlanningGraphDomains.capture(filter, PlanningGraphDomain.defaultGraph());
		return filter;
	}
}
